/// **AR86-C6.** The rule set of the last floor this CHECKOUT itself saw fully authenticated, kept outside the
/// document itself (see [`FloorIdentity`]) so a later reconstruction of the floor from the repository's current
/// on-disk shape (`crate::init::native_layout_rules`, run only once the authenticated record has already become
/// untrustworthy — `crate::policy::PolicySet::load`) can be checked against it rather than trusting the current
/// shape alone. Empty when this checkout has never seen an authenticated floor at all.
pub fn last_known_adoption_floor_rules(root: &Path) -> Vec<Value> {
    FloorIdentity::last_known_rules(root)
}

